PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,quota_key TEXT NOT NULL,provider TEXT NOT NULL,created_at INTEGER NOT NULL,generation INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS auth_accounts(provider TEXT NOT NULL,subject_hash TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(provider,subject_hash));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL,created_at INTEGER NOT NULL,recent_auth INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS auth_transactions(state_hash TEXT PRIMARY KEY,cookie_hash TEXT NOT NULL,provider TEXT NOT NULL,secret_cipher TEXT NOT NULL,intent TEXT NOT NULL,user_id TEXT,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pending_signup(token_hash TEXT PRIMARY KEY,provider TEXT NOT NULL,subject_hash TEXT NOT NULL,quota_key TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS consents(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,purpose TEXT NOT NULL,version TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,purpose));
CREATE TABLE IF NOT EXISTS reservations(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,quota_key TEXT,day TEXT NOT NULL,month TEXT NOT NULL,request_key TEXT NOT NULL,request_hash TEXT NOT NULL,stage TEXT NOT NULL,birth_hash TEXT NOT NULL,generation INTEGER NOT NULL,status TEXT NOT NULL,max_cost INTEGER NOT NULL,actual_cost INTEGER NOT NULL DEFAULT 0,cost_estimated INTEGER NOT NULL DEFAULT 0,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,thinking_tokens INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,deadline INTEGER NOT NULL,UNIQUE(quota_key,request_key));
CREATE INDEX IF NOT EXISTS reservation_quota_day ON reservations(quota_key,day,status);
CREATE INDEX IF NOT EXISTS reservation_deadline ON reservations(status,deadline);
CREATE TABLE IF NOT EXISTS budgets(bucket TEXT PRIMARY KEY,spent INTEGER NOT NULL DEFAULT 0,reserved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS saved_items(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('birth','conversation')),cipher TEXT NOT NULL,created_at INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS saved_owner ON saved_items(user_id,kind);
CREATE TABLE IF NOT EXISTS unlink_events(id TEXT PRIMARY KEY,provider TEXT NOT NULL,status TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS action_rates(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
